void VMC_Data_Get(Leg_State_t* Leg_State , float phi4, float dphi4, float phi1, float dphi1)//整合位置，速度，雅可比矩阵的求解
{
    Leg_State->last_dl0 = Leg_State->this_dl0;
    Leg_State->phi4 = phi4;
    Leg_State->phi1 = phi1;
    Leg_State->dphi4 = dphi4;
    Leg_State->dphi1 = dphi1;

    leg_pos(phi1,phi4,Leg_State->pos);
    Leg_State->l0 = Leg_State->pos[0];
    Leg_State->phi0 = Normalize_Angle_PI(Leg_State->pos[1]-1.57f);
    leg_spd(Leg_State->dphi1, Leg_State->dphi4, Leg_State->phi1, Leg_State->phi4, Leg_State->spd);
    Leg_State->dl0 = Leg_State->spd[0];
    Leg_State->this_dl0 = Leg_State->dl0;
    Leg_State->dphi0 = Leg_State->spd[1];
    Leg_State->ddl0 = (Leg_State->this_dl0 - Leg_State->last_dl0) / (TIME_STEP * 0.001);//可能要加低通滤波器

    leg_J_cal(phi1,phi4,Leg_State->J);
    for (int i = 0; i < 2; i++)
    {
        for (int j = 0; j < 2; j++)
        {
                Leg_State->j[j][i] = Leg_State->J[i * 2 + j];
        }
    }
}



